        var b = el('button', 'h-9 px-3 rounded font-semibold text-sm shrink-0 transition-all ' +
          (secili ? 'bg-primary-base text-black' : 'bg-secondary-base text-white hover:brightness-125'), t(o[1]));
        b.style.cssText = 'border:0;cursor:pointer';
        b.addEventListener('click', function () {
          var y = {}; y[p[0]] = o[0];
          sendBg({ type: 'setSettings', payload: y }); settings[p[0]] = o[0]; panelCiz();
        });
        sr2.appendChild(b);
