  function bolumGelismis(body) {
    // --- yedek ---
    var y = kart(t('pkAyarYedegi'), t('pkAyarYedegiD'));
    var yr = el('div', 'flex flex-wrap gap-2');
    var db = btnBirincil(t('pkDisaAktar'));
    db.addEventListener('click', function () { yedekIndir(); });
    yr.appendChild(db);

    var ib = btnIkincil(t('pkIceAktar'));
    var giris = el('input', '');
    giris.type = 'file'; giris.accept = 'application/json,.json';
    giris.style.cssText = 'display:none';
    giris.addEventListener('change', function () {
      var f = giris.files && giris.files[0];
      giris.value = '';
      if (!f) return;
      if (f.size > 5 * 1024 * 1024) { toast(t('pkTYedekCokBuyuk')); return; }
      var fr = new FileReader();
      fr.onload = function () { yedekOnayAc(String(fr.result || '')); };
      fr.onerror = function () { toast(t('pkTYedekOkunamadi')); };
      fr.readAsText(f);
    });
    ib.addEventListener('click', function () { giris.click(); });
    yr.appendChild(ib);
    yr.appendChild(giris);
    y.appendChild(yr);
    y.appendChild(el('div', 'text-xs text-subtle', t('pkYedekNot')));
    body.appendChild(y);

    // --- sıfırlama ---
    var sf = kart(t('pkHersiSifirla'), t('pkHersiSifirlaD'));
    var sb = btnIkincil(t('pkHersiSifirla'));
    sb.style.setProperty('color', '#fa2d2d', 'important');
    sb.addEventListener('click', function () { sifirlaOnayAc(); });
    var sr = el('div', 'flex'); sr.appendChild(sb);
    sf.appendChild(sr);
    body.appendChild(sf);

    // --- tanıtımı yeniden göster ---
    /* Tanıtım tek sefer çıkıyor; kapattıktan sonra ulaşılacak bir yer
       olmazsa bir daha hiç görülemezdi. */
    var tn = kart(t('pkTanBaslik'), t('pkTanBaslikD'));
    var tnB = btnIkincil(t('pkTanGoster'));
    tnB.addEventListener('click', function (e) {
      e.preventDefault(); e.stopPropagation();
      try { pkAyarSayfaKapat(); } catch (er) {}
      try { pkTanitimAc(true); } catch (er) {}
    });
    var tnR = el('div', 'flex'); tnR.appendChild(tnB);
    tn.appendChild(tnR);
    body.appendChild(tn);

    // --- sürüm notları ---
    var sn = kart(t('pkSurumNotlari'), t('pkSurumNotlariD'));
    SURUM_NOTLARI.forEach(function (p) {
      var blok = el('div', 'flex flex-col gap-1');
      var bas = el('div', 'flex items-center gap-2');
      var rz = el('span', 'text-xs font-bold');
      rz.style.cssText = 'background:rgb(83,252,24);color:#000;border-radius:3px;padding:1px 6px';
      rz.textContent = 'v' + p[0];
      bas.appendChild(rz);
      blok.appendChild(bas);
      p[1].forEach(function (k) {
        var r = el('div', 'flex items-start gap-2');
        var art = el('span', 'text-primary-base font-bold shrink-0', '+');
        r.appendChild(art);
        r.appendChild(el('div', 'text-sm text-subtle', t(k)));
        blok.appendChild(r);
      });
      sn.appendChild(blok);
    });
    body.appendChild(sn);
  }

  /* İçe aktarma onayı: hangi dosya, kaç anahtar, hangi yöntem. */
  function yedekOnayAc(metin) {
    var d = yedekDogrula(metin);
    if (d.hata) { toast(t(d.hata)); return; }
    var kap = pkDiyalog(t('pkIceAktar'));
    kap.govde.appendChild(el('div', 'text-sm text-subtle',
      t('pkYedekOzet', [String(d.sayi), d.tarih ? d.tarih.slice(0, 10) : '—'])));
    var sr = el('div', 'flex flex-col gap-2');
    [[t('pkBirlestir'), t('pkBirlestirD'), false], [t('pkSifirdan'), t('pkSifirdanD'), true]].forEach(function (p) {
      var b = el('button', 'bg-surface-highest hover:brightness-125 rounded text-left flex flex-col gap-1');
      b.style.cssText = 'padding:10px 12px;border:0;cursor:pointer';
      b.appendChild(el('div', 'text-sm font-semibold text-white', p[0]));
      b.appendChild(el('div', 'text-xs text-subtle', p[1]));
      b.addEventListener('click', function () {
        yedekUygula(d.veri, p[2], function (ok) {
          kap.kapat();
          if (!ok) { toast(t('pkTYedekUygulanamadi')); return; }
          toast(t('pkTYedekUygulandi'));
          setTimeout(function () { location.reload(); }, 900);
        });
      });
      sr.appendChild(b);
    });
    kap.govde.appendChild(sr);
  }

  function sifirlaOnayAc() {
    var kap = pkDiyalog(t('pkEminMisin'));
    kap.govde.appendChild(el('div', 'text-sm text-subtle', t('pkHersiSifirlaUyari')));
    var sr = el('div', 'flex gap-2');
    var ev = el('button', 'flex-1 h-9 rounded font-semibold text-sm text-white', t('pkEvetSifirla'));
    ev.style.cssText = 'background:#fa2d2d;border:0;cursor:pointer';
    ev.addEventListener('click', function () {
      hersiSifirla(function (ok) {
        kap.kapat();
        if (!ok) { toast(t('pkTSifirlanamadi')); return; }
        toast(t('pkTSifirlandi'));
        setTimeout(function () { location.reload(); }, 900);
      });
    });
    var hy = btnIkincil(t('pkIptal'));
    hy.style.flex = '1';
    hy.addEventListener('click', function () { kap.kapat(); });
    sr.appendChild(hy); sr.appendChild(ev);
    kap.govde.appendChild(sr);
  }

  /* Ortak küçük diyalog — Kick'in kendi kutu sınıflarıyla, ortalanmış. */
  var PKDIYALOG_ID = 'pk-diyalog';
  function pkDiyalog(baslik) {
    var e0 = document.getElementById(PKDIYALOG_ID); if (e0) e0.remove();
    var ort = el('div', '');
    ort.id = PKDIYALOG_ID;
    ort.style.cssText = 'position:fixed;inset:0;z-index:2147483200;background:rgba(0,0,0,.6);' +
      'display:flex;align-items:center;justify-content:center;padding:20px';
    var k = el('div', 'bg-surface-base rounded shadow-lg flex flex-col gap-3 ' +
      'will-change-[opacity,transform] animate-slideUpAndFade');
    k.style.cssText = 'width:min(420px,92vw);padding:16px;border:1px solid rgba(240,241,242,.16)';
    var bas = el('div', 'flex items-center justify-between gap-2');
    bas.appendChild(el('div', 'text-md font-bold text-white lg:font-semibold', baslik));
    var kb = el('button', 'inline-flex items-center justify-center rounded state-layer-surface text-white shrink-0');
    kb.style.cssText = 'width:24px;height:24px;padding:0;background:none;border:0;cursor:pointer';
    kb.innerHTML = I_KAPAT;
    function kapat() { if (ort.parentNode) ort.remove(); }
    kb.addEventListener('click', kapat);
    bas.appendChild(kb);
    k.appendChild(bas);
    var govde = el('div', 'flex flex-col gap-3');
    k.appendChild(govde);
    ort.appendChild(k);
    ort.addEventListener('click', function (e) { if (e.target === ort) kapat(); });
    pkKatmanaEkle(ort);
    return { kap: k, govde: govde, kapat: kapat };
  }


