  var paylasOnbellek = null;
  function paylasButonu() {
    if (paylasOnbellek && paylasOnbellek.isConnected) return paylasOnbellek;
    var bulunan = paylasButonuAra();
    if (bulunan) paylasOnbellek = bulunan;
    return bulunan;
  }

  function paylasButonuAra() {
    var v = oynaticiVideosu();
    var vb = v ? v.getBoundingClientRect().bottom : 0;
    var bs = document.querySelectorAll('button');
    for (var i = 0; i < bs.length; i++) {
      var et = (bs[i].getAttribute('aria-label') || bs[i].title || '');
      if (!/payla|share/i.test(et)) continue;
      var r = bs[i].getBoundingClientRect();
      if (!r.width || !r.height) continue;              // gizli kopya
      if (vb && r.top < vb) continue;                   // videonun üstündekiler değil
      if (profilKartiIcinde(bs[i])) continue;
      return bs[i];
    }
    return null;
  }

  function engelleIkonuKur() {
    if (!settings.consented) return;
    var slug = sayfaSlug();
    // `t` DEĞİL: var yükseldiği için aşağıdaki t('...') çağrısı "t is not a function" veriyordu.
    if (!slug) { var es = document.querySelectorAll('[data-pk-block2]'); for (var q = 0; q < es.length; q++) es[q].remove(); return; }
    var pay = paylasButonu(); if (!pay || !pay.parentElement) return;
    var bar = pay.parentElement;
    var engelli = !!blocked[slug];
    var mevcut = bar.querySelector(':scope > [data-pk-block2]');
    if (mevcut) {
      if (mevcut.getAttribute('data-pk-block2') === (engelli ? '1' : '0')) return;
      mevcut.remove();
    }
    /* Paylaş/şikayet butonlarıyla aynı ölçü ve yüzey — Kick'in kendi sınıfları. */
    var b = el('button', 'group relative box-border flex shrink-0 grow-0 select-none items-center ' +
      'justify-center rounded state-layer-surface bg-transparent text-white');
    b.style.cssText = 'width:40px;height:40px;padding:0;border:0;cursor:pointer';
    b.setAttribute('data-pk-block2', engelli ? '1' : '0');
    b.type = 'button';
    /* Kick’in kendi ipucu görünümü — yanındaki Paylaş/Şikâyet düğmeleri de
       aynısını kullanıyor. Ham `title` bırakılsaydı işletim sisteminin gri
       kutusu çıkıp Kick’inkiyle iki farklı ipucu olurdu. */
    b.setAttribute('aria-label', t(engelli ? 'pkKanalEngeliKaldir' : 'pkKanaliGizle'));
    /* 10px: oynatıcı şeridindeki 2px burada ipucunu düğmenin üstüne
       bindiriyordu — bu satırdaki düğmeler daha sıkışık. */
    bindTip(b, t(engelli ? 'pkKanalEngeliKaldir' : 'pkKanaliGizle'), true, 10);
    b.innerHTML = I_BLOCK;
    if (engelli) b.style.color = 'rgb(83,252,24)';
    b.addEventListener('click', function (e) {
      e.preventDefault(); e.stopPropagation();
      if (blocked[slug]) unblockChannel(slug); else blockChannel(slug);
      engelleIkonuKur();
      toast(t(blocked[slug] ? 'pkTKanalGizlendi' : 'pkTKanalGizlemeKalkti'));
    });
    // paylaşın HEMEN SAĞINA (şikayet etten önce)
    if (pay.nextSibling) bar.insertBefore(b, pay.nextSibling); else bar.appendChild(b);
    ikonEsitle(b, bar);                        // paylas/sikayet ikonlariyla ayni boy
  }


